using System.Runtime.InteropServices;
using NovaCore.Core;
using NovaCore.Graphics;
using NovaCore.Interop;

var tests=new (string,Action)[]{("MeshHandle",MeshHandleTest),("Transport layout",LayoutTest),("Transform conversion",TransformTest),("Camera relative",RelativeTest),("Batches and capacity",BatchTest)};
foreach(var (name,test) in tests){test();Console.WriteLine($"PASS {name}");}

static void MeshHandleTest(){Check(!MeshHandle.Invalid.IsValid,"zero invalid");Check(MeshHandle.Triangle.IsValid,"triangle valid");}
static void LayoutTest(){Check(Marshal.SizeOf<NativeEncodedPosition>()==32,"encoded size");Check(Marshal.SizeOf<NativeCameraData>()==96,"native camera size");Check(Marshal.OffsetOf<NativeCameraData>(nameof(NativeCameraData.Position)).ToInt32()==0,"native camera position offset");Check(Marshal.OffsetOf<NativeCameraData>(nameof(NativeCameraData.ViewProjection)).ToInt32()==32,"native camera matrix offset");Check(Marshal.SizeOf<GpuCameraData>()==96,"GPU camera size");Check(Marshal.OffsetOf<GpuCameraData>(nameof(GpuCameraData.Position)).ToInt32()==0,"GPU camera position offset");Check(Marshal.OffsetOf<GpuCameraData>(nameof(GpuCameraData.ViewProjection)).ToInt32()==32,"GPU camera matrix offset");Check(Marshal.SizeOf<NativeRenderTransform>()==32,"transform size");Check(Marshal.SizeOf<NativeRenderObject>()==80,"object stride");Check(Marshal.OffsetOf<NativeRenderObject>(nameof(NativeRenderObject.Position)).ToInt32()==0,"position offset");Check(Marshal.OffsetOf<NativeRenderObject>(nameof(NativeRenderObject.Transform)).ToInt32()==32,"transform offset");Check(Marshal.OffsetOf<NativeRenderObject>(nameof(NativeRenderObject.Mesh)).ToInt32()==64,"mesh offset");Check(Marshal.SizeOf<NativeDrawBatch>()==16,"batch stride");Check(Marshal.SizeOf<NativeInputState>()==48,"input size");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.DeltaSeconds)).ToInt32()==0,"input delta offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveLeft)).ToInt32()==4,"input left offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveRight)).ToInt32()==8,"input right offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveForward)).ToInt32()==12,"input forward offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveBackward)).ToInt32()==16,"input backward offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveDown)).ToInt32()==20,"input down offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MoveUp)).ToInt32()==24,"input up offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.Reset)).ToInt32()==28,"input reset offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.LookActive)).ToInt32()==32,"input look offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MouseDeltaX)).ToInt32()==36,"input x offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MouseDeltaY)).ToInt32()==40,"input y offset");Check(Marshal.OffsetOf<NativeInputState>(nameof(NativeInputState.MouseWheelDetents)).ToInt32()==44,"input wheel offset");Check(NativeRuntime.GetAbiLayout(out var abi)==NativeResult.Success&&abi.CameraDataSize==96&&abi.CameraPositionOffset==0&&abi.CameraViewProjectionOffset==32&&abi.RenderObjectSize==80&&abi.RenderObjectTransformOffset==32&&abi.RenderObjectMeshOffset==64&&abi.InputStateSize==48&&abi.InputDeltaSecondsOffset==0&&abi.InputMoveLeftOffset==4&&abi.InputMoveRightOffset==8&&abi.InputMoveForwardOffset==12&&abi.InputMoveBackwardOffset==16&&abi.InputMoveDownOffset==20&&abi.InputMoveUpOffset==24&&abi.InputResetOffset==28&&abi.InputLookActiveOffset==32&&abi.InputMouseDeltaXOffset==36&&abi.InputMouseDeltaYOffset==40&&abi.InputMouseWheelDetentsOffset==44,"native input ABI layout");}
static void TransformTest(){var t=RenderTransform.FromAuthoritative(new DoubleQuaternion(0,0,Math.Sqrt(.5),Math.Sqrt(.5)),new Double3(-1,2,3));Check(t.Rotation.W>.7f&&t.Scale.X==-1,"conversion/negative scale policy");Check(FloatQuaternion.Identity==new FloatQuaternion(0,0,0,1),"identity");}
static void RelativeTest(){var camera=EncodedPosition.Encode(new Double3(4e12,-3e12,7e12));var positive=EncodedPosition.Resolve(EncodedPosition.Encode(new Double3(4e12+.25,-3e12,7e12)),camera);var negative=EncodedPosition.Resolve(EncodedPosition.Encode(new Double3(4e12-.25,-3e12,7e12)),camera);Check(positive.Value.X>0&&negative.Value.X<0,"relative signs");}
static void BatchTest(){var frame=new ReferenceFrameId(1);var position=new UniversePosition(new Double3(4e12,0,0),frame);var camera=new GpuCameraData{Position=EncodedPosition.Encode(position.Value),ViewProjection=new Float4x4{C0R0=1,C1R1=1,C2R2=1,C3R3=1}};var s=new RenderFrameSubmission(1000);s.Begin(camera);for(var i=0;i<1000;i++)s.Add(new UniversePosition(new Double3(4e12+i,0,0),frame),new DoubleQuaternion(0,0,0,1),new Double3(1,1,1),MeshHandle.Triangle);s.Complete();Check(s.ObjectCount==1000&&s.BatchCount==1&&s.Batches[0].ObjectCount==1000,"automatic stable batch");var small=new RenderFrameSubmission(1);small.Begin(camera);small.Add(position,new DoubleQuaternion(0,0,0,1),new Double3(1,1,1),MeshHandle.Triangle);try{small.Add(position,new DoubleQuaternion(0,0,0,1),new Double3(1,1,1),MeshHandle.Triangle);throw new Exception("capacity not rejected");}catch(InvalidOperationException){}var invalid=new RenderFrameSubmission(2);invalid.Begin(camera);try{invalid.Add(position,new DoubleQuaternion(0,0,0,1),new Double3(1,1,1),MeshHandle.Invalid);throw new Exception("invalid mesh not rejected");}catch(ArgumentOutOfRangeException){}}
static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
